def isok(x):
    x = str(x)
    for i in range(len(x)//2):
        if x[i] != x[-i-1]:
            return False
    return True

def find_max_palindromic_cube(N):
    ans = 0
    i = 1
    while True:
        i_cubed = i**3
        if i_cubed > N:
            break
        if isok(i_cubed):
            ans = i_cubed
        i += 1
    return ans
